                    return True
                if self.pre_ids is None or other.pre_ids is None:
                    return False
                if len(self.pre_ids) != len(other.pre_ids):
                    return False
                for a, b in zip(self.pre_ids, other.pre_ids):
                    if cmp_id(a, b) != 0:
                        return False
                return True

        return K(major, minor, patch, pre_ids)

